def _validate_w4_stream(handle: Any, offset: int, shape: Sequence[int]) -> None:
    groups = shape[0] * (shape[1] // 128)
    code_start = offset + groups * 2
    for start in range(0, groups, GROUP_CHUNK):
        count = min(GROUP_CHUNK, groups - start)
